gK1(){return"\u041d\u0430\u0437\u0432\u0430 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u0457"},
gKV(){return"\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0441\u043f\u0438\u0441\u043e\u043a?"},
KU(a){return"\xab"+a+"\xbb \u0456 \u0432\u0441\u0456 \u0439\u043e\u0433\u043e \u0442\u043e\u0432\u0430\u0440\u0438 \u0431\u0443\u0434\u0435 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e."},
gCJ(){return"\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f"},
gKp(){return"\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u043a\u043e\u0434"},
gK4(){return"\u0434\u0435\u0448\u0435\u0432\u0448\u0435"},
G8(a){return"\u0421\u0445\u043e\u0436\u0438\u0439 \u0442\u043e\u0432\u0430\u0440: "+a},
gzo(){return"\u0417\u0432\u0438\u0447\u043d\u0438\u0439 \u043a\u043e\u0448\u0438\u043a"},
gOL(){return"\u0422\u043e\u0432\u0430\u0440\u0438 \u0437 \u0432\u0430\u0448\u0438\u0445 \u043e\u0441\u0442\u0430\u043d\u043d\u0456\u0445 \u043f\u043e\u0445\u043e\u0434\u0456\u0432. \u0417\u043d\u0456\u043c\u0456\u0442\u044c \u0437\u0430\u0439\u0432\u0435 \u2014 \u0456 \u043f\u043e\u0437\u043d\u0430\u0447\u0442\u0435 \u0432\u0441\u0435 \u0440\u0430\u0437\u043e\u043c."},
gON(){return"\u041f\u043e\u043a\u0438 \u0437\u0430\u043c\u0430\u043b\u043e \u0456\u0441\u0442\u043e\u0440\u0456\u0457. \u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044c \u0445\u043e\u0447\u0430 \u0431 \u0434\u0432\u0430 \u043f\u043e\u0445\u043e\u0434\u0438 \u043a\u043d\u043e\u043f\u043a\u043e\u044e \xab\u041d\u043e\u0432\u0438\u0439 \u043f\u043e\u0445\u0456\u0434\xbb \u2014 \u0456 \u0442\u0443\u0442 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0432\u0430\u0448 \u0437\u0432\u0438\u0447\u043d\u0438\u0439 \u043a\u043e\u0448\u0438\u043a."},
OO(a,b){return""+a+" \u0437 "+b},
OM(a){return"\u041f\u043e\u0437\u043d\u0430\u0447\u0438\u0442\u0438 ("+a+")"},
